namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple and delicious pizza with fresh mozzarella and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes evenly.", "Tear mozzarella and distribute over sauce.", "Bake for 10-12 minutes until crust is golden.", "Top with fresh basil and a drizzle of olive oil."],
            AverageRating = 4.5, RatingCount = 24
        },
        new()
        {
            Id = 2, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken in a creamy, spiced tomato sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger", "Rice"],
            Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or pan-sear chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer 15 minutes.", "Stir in cream and cooked chicken.", "Serve over basmati rice."],
            AverageRating = 4.8, RatingCount = 42
        },
        new()
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "A Roman classic with eggs, cheese, and pancetta.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps = ["Cook spaghetti in salted water until al dente.", "Fry pancetta until crispy.", "Whisk eggs with grated pecorino and pepper.", "Toss hot pasta with pancetta.", "Remove from heat and stir in egg mixture.", "Serve immediately with extra cheese."],
            AverageRating = 4.6, RatingCount = 31
        },
        new()
        {
            Id = 4, Title = "Beef Tacos", Category = "Mexican",
            Description = "Quick and flavorful ground beef tacos with fresh toppings.",
            Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Lime"],
            Steps = ["Brown ground beef in a skillet.", "Add taco seasoning and water, simmer 5 minutes.", "Warm tortillas in a dry pan.", "Assemble tacos with beef and toppings.", "Squeeze lime juice over tacos.", "Serve with salsa on the side."],
            AverageRating = 4.3, RatingCount = 18
        },
        new()
        {
            Id = 5, Title = "Pad Thai", Category = "Thai",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Tamarind paste", "Fish sauce", "Lime", "Green onions"],
            Steps = ["Soak rice noodles in warm water for 30 minutes.", "Stir-fry shrimp until pink, set aside.", "Scramble eggs in the same pan.", "Add noodles, tamarind paste, and fish sauce.", "Toss with shrimp, bean sprouts, and peanuts.", "Garnish with lime wedges and green onions."],
            AverageRating = 4.7, RatingCount = 35
        },
        new()
        {
            Id = 6, Title = "Guacamole", Category = "Mexican",
            Description = "Fresh and zesty avocado dip, perfect as a starter.",
            Ingredients = ["Avocados", "Lime juice", "Red onion", "Cilantro", "Jalapeño", "Tomato", "Salt"],
            Steps = ["Halve and pit the avocados.", "Mash avocado flesh in a bowl.", "Dice onion, tomato, jalapeño, and cilantro.", "Mix everything together.", "Add lime juice and salt to taste.", "Serve immediately with tortilla chips."],
            AverageRating = 4.4, RatingCount = 22
        },
        new()
        {
            Id = 7, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Description = "Classic chewy cookies loaded with chocolate chips.",
            Ingredients = ["Butter", "Sugar", "Brown sugar", "Eggs", "Vanilla extract", "All-purpose flour", "Baking soda", "Salt", "Chocolate chips"],
            Steps = ["Preheat oven to 375°F.", "Cream butter and sugars until fluffy.", "Beat in eggs and vanilla.", "Mix in flour, baking soda, and salt.", "Fold in chocolate chips.", "Drop spoonfuls onto baking sheet and bake 9-11 minutes."],
            AverageRating = 4.9, RatingCount = 56
        },
        new()
        {
            Id = 8, Title = "Green Curry", Category = "Thai",
            Description = "Aromatic coconut-based curry with vegetables and chicken.",
            Ingredients = ["Green curry paste", "Coconut milk", "Chicken thighs", "Bamboo shoots", "Thai basil", "Fish sauce", "Palm sugar", "Jasmine rice"],
            Steps = ["Heat curry paste in a pot until fragrant.", "Add half the coconut milk and stir.", "Add sliced chicken and cook through.", "Pour in remaining coconut milk and bamboo shoots.", "Season with fish sauce and palm sugar.", "Serve over jasmine rice topped with Thai basil."],
            AverageRating = 4.5, RatingCount = 28
        }
    ];

    private readonly Lock _lock = new();

    public IReadOnlyList<string> GetCategories()
    {
        lock (_lock)
        {
            return _recipes.Select(r => r.Category).Distinct().Order().ToList();
        }
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        lock (_lock)
        {
            return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
        }
    }

    public Recipe? GetById(int id)
    {
        lock (_lock)
        {
            return _recipes.FirstOrDefault(r => r.Id == id);
        }
    }

    public void AddRating(int recipeId, int stars)
    {
        lock (_lock)
        {
            var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
            if (recipe is null || stars is < 1 or > 5) return;

            var totalStars = recipe.AverageRating * recipe.RatingCount + stars;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round(totalStars / recipe.RatingCount, 1);
        }
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        lock (_lock)
        {
            var recipe = new Recipe
            {
                Id = _recipes.Max(r => r.Id) + 1,
                Title = submission.Title,
                Category = submission.Category,
                Description = $"A community-submitted {submission.Category.ToLowerInvariant()} recipe.",
                Ingredients = submission.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList(),
                Steps = submission.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).ToList()
            };
            _recipes.Add(recipe);
            return recipe;
        }
    }
}

