@rendermode InteractiveServer
@using RecipeCommunity.Services
@inject RecipeService RecipeService

<div class="d-inline-flex align-items-center gap-1">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <button class="btn btn-link p-0 fs-4 text-decoration-none"
                @onclick="() => SubmitRating(star)"
                disabled="@submitted"
                title="Rate @star star(s)">
            <span class="@(star <= (hoveredStar > 0 ? hoveredStar : selectedStar) ? "text-warning" : "text-secondary")"
                  @onmouseover="() => hoveredStar = star"
                  @onmouseout="() => hoveredStar = 0">
                ★
            </span>
        </button>
    }

    @if (submitted)
    {
        <span class="text-success ms-2">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int selectedStar;
    private int hoveredStar;
    private bool submitted;

    private void SubmitRating(int stars)
    {
        if (submitted) return;
        selectedStar = stars;
        RecipeService.AddRating(RecipeId, stars);
        submitted = true;
    }
}

