@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models
@using RecipeCommunity.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<h2>📝 Submit a Recipe</h2>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (!string.IsNullOrEmpty(errorMessage))
{
    <div class="alert alert-danger">@errorMessage</div>
}

<EditForm Model="submission" OnValidSubmit="HandleSubmit" FormName="SubmitRecipe">
    <div class="mb-3">
        <label class="form-label" for="title">Recipe Title</label>
        <InputText id="title" class="form-control" @bind-Value="submission.Title" placeholder="e.g., Grandma's Apple Pie" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="category">Category</label>
        <InputSelect id="category" class="form-select" @bind-Value="submission.Category">
            <option value="">-- Select a category --</option>
            @foreach (var cat in categories)
            {
                <option value="@cat">@cat</option>
            }
            <option value="Other">Other</option>
        </InputSelect>
    </div>

    <div class="mb-3">
        <label class="form-label" for="ingredients">Ingredients</label>
        <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="submission.Ingredients"
                       placeholder="One ingredient per line&#10;e.g.,&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        <div class="form-text">Enter one ingredient per line.</div>
    </div>

    <div class="mb-3">
        <label class="form-label" for="steps">Steps</label>
        <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="submission.Steps"
                       placeholder="One step per line&#10;e.g.,&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients" />
        <div class="form-text">Enter one step per line.</div>
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
    <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
</EditForm>

@code {
    private RecipeSubmission submission = new();
    private IReadOnlyList<string> categories = [];
    private string? errorMessage;

    protected override void OnInitialized()
    {
        categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(submission.Title) ||
            string.IsNullOrWhiteSpace(submission.Category) ||
            string.IsNullOrWhiteSpace(submission.Ingredients) ||
            string.IsNullOrWhiteSpace(submission.Steps))
        {
            errorMessage = "Please fill in all fields.";
            return;
        }

        var recipe = RecipeService.AddRecipe(submission);
        Navigation.NavigateTo($"recipe/{recipe.Id}");
    }
}
